[("Que refuse Inès ?", "Une certitude sur une cause non isolée.", "Toute enquête.", "L’existence de la baisse.", "son effet n’est pas isolé"), ("Que propose-t-elle de vérifier ?", "Les voies d’information et les obstacles à la venue.", "Les préférences musicales uniquement.", "Le résultat d’une enquête déjà terminée.", "ce qui les empêche de venir")],
[("faute de", "for lack of"), ("tout en", "while at the same time"), ("néanmoins", "nevertheless")],
