[("Archiviste", "Voici les lettres auxquelles je faisais référence."), ("Collègue", "Sont-ce celles dont la famille autorise la reproduction ?"), ("Archiviste", "Pas toutes. Cette liste distingue les autorisations reçues."), ("Collègue", "Et le carnet près duquel elles étaient rangées ?"), ("Archiviste", "Il provient d’un autre dépôt."), ("Collègue", "Précisons-le pour éviter un lien artificiel.")],
[("Toutes les lettres sont-elles reproductibles ?", "Non, les autorisations diffèrent.", "Oui, sans distinction.", "Aucune liste n’existe.", "Pas toutes"), ("Pourquoi préciser l’origine du carnet ?", "Pour éviter un lien artificiel.", "Pour augmenter son prix.", "Pour supprimer les lettres.", "éviter un lien artificiel")],
