[("Que demande l’animatrice après l’interruption ?", "De laisser terminer l’explication.", "De renoncer à tout exemple.", "De voter immédiatement.", "Laissons aussi terminer l’explication"), ("Quelle réserve accompagne l’accord final ?", "Prévoir une réponse libre.", "Supprimer le questionnaire.", "Interroger une seule personne.", "laisser une réponse libre")],
