[("Rédactrice", "Le chiffre est exact, pourquoi le modifier ?"), ("Lecteur", "Je ne demande pas de le changer, mais d’expliquer la base de comparaison."), ("Rédactrice", "Une phrase supplémentaire suffirait-elle ?"), ("Lecteur", "Oui, avec un lien vers la méthode."), ("Rédactrice", "Je préciserai aussi qu’il s’agit d’entrées."), ("Lecteur", "Cela évitera de les confondre avec des visiteurs distincts.")],
[("Le lecteur demande-t-il de changer le résultat ?", "Non, d’expliquer la comparaison.", "Oui, de le doubler.", "Oui, de cacher la source.", "d’expliquer la base de comparaison"), ("Quelle confusion faut-il éviter ?", "Entrées et visiteurs distincts.", "Livres et journaux uniquement.", "Mois et années scolaires.", "visiteurs distincts")],
[("tout en rappelant", "while pointing out"), ("induire en erreur", "to mislead"), ("la base de comparaison", "the comparison baseline")],
