[("Qu’est-ce qui est confirmé ?", "Le bâtiment.", "La date exacte.", "Tous les horaires de transport.", "Le bâtiment est choisi"), ("Que préciser dans la demande de réponse ?", "Les destinataires concernés et le canal.", "Un engagement inexistant.", "Le nom de tous les anciens bureaux.", "les personnes concernées et le canal de réponse")],
